public class CrashBlameAggregatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static final String TRACE_A = String.join("\n",
            "java.lang.NullPointerException",
            "    at com.shop.order.OrderService.total(OrderService.java:42)",
            "    at com.shop.order.OrderService.total(OrderService.java:40)",
            "    at com.shop.web.CartController.show(CartController.java:17)");

    static final String TRACE_B = String.join("\n",
            "java.lang.IllegalStateException",
            "    at com.shop.order.OrderService.apply(OrderService.java:88)",
            "    at com.shop.pay.PaymentGateway.charge(PaymentGateway.java:12)");

    static final String TRACE_C = String.join("\n",
            "java.lang.ArithmeticException",
            "    at com.shop.pay.PaymentGateway.charge(PaymentGateway.java:15)",
            "Caused by: java.lang.Error",
            "    at com.shop.order.OrderService.fee(OrderService.java:9)",
            "    at sun.misc.Unsafe.park(Native Method)");

    public static void main(String[] args) {
        CrashBlameAggregator blame = new CrashBlameAggregator();
        check("mostBlamed before any trace", "", blame.mostBlamed());
        check("report before any trace", "", blame.report());

        blame.addTrace(TRACE_A);
        blame.addTrace(TRACE_B);
        blame.addTrace(TRACE_C);

        check("traceCount", 3, blame.traceCount());
        check("a class repeated in one trace counts once", 3, blame.blameCount("OrderService"));
        check("blameCount of a second class", 2, blame.blameCount("PaymentGateway"));
        check("blameCount of a once-seen class", 1, blame.blameCount("CartController"));
        check("a frame with no line number still counts", 1, blame.blameCount("Unsafe"));
        check("blameCount of a class never seen", 0, blame.blameCount("Nowhere"));
        check("mostBlamed", "OrderService", blame.mostBlamed());
        check("report is ordered by count then name",
                "OrderService: 3\nPaymentGateway: 2\nCartController: 1\nUnsafe: 1", blame.report());

        CrashBlameAggregator tie = new CrashBlameAggregator();
        tie.addTrace("Error\n    at com.a.Zebra.go(Zebra.java:1)\n    at com.a.Apple.go(Apple.java:2)");
        check("a tie is broken alphabetically", "Apple", tie.mostBlamed());
        finish();
    }
}

