public class CrashBlameAggregator {

    private final java.util.Map<String, Integer> counts = new java.util.TreeMap<>();
    private int traces = 0;

    public void addTrace(String trace) {
        traces++;
        java.util.Set<String> seen = new java.util.TreeSet<>();
        for (String line : trace.split("\n", -1)) {
            String simple = simpleClassName(line.trim());
            if (simple != null) {
                seen.add(simple);
            }
        }
        for (String name : seen) {
            counts.put(name, counts.getOrDefault(name, 0) + 1);
        }
    }

    public int traceCount() {
        return traces;
    }

    public int blameCount(String simpleName) {
        return counts.getOrDefault(simpleName, 0);
    }

    public String mostBlamed() {
        String best = "";
        int bestCount = 0;
        for (java.util.Map.Entry<String, Integer> entry : counts.entrySet()) {
            if (entry.getValue() > bestCount) {
                bestCount = entry.getValue();
                best = entry.getKey();
            }
        }
        return best;
    }

    public String report() {
        java.util.List<String> names = new java.util.ArrayList<>(counts.keySet());
        names.sort(java.util.Comparator
                .comparingInt((String name) -> counts.get(name)).reversed()
                .thenComparing(java.util.Comparator.naturalOrder()));
        StringBuilder out = new StringBuilder();
        for (String name : names) {
            if (out.length() > 0) {
                out.append("\n");
            }
            out.append(name).append(": ").append(counts.get(name));
        }
        return out.toString();
    }

    private static String simpleClassName(String line) {
        if (!line.startsWith("at ")) {
            return null;
        }
        String text = line.substring(3).trim();
        int paren = text.indexOf('(');
        if (paren < 0) {
            return null;
        }
        String head = text.substring(0, paren);
        int methodDot = head.lastIndexOf('.');
        if (methodDot < 0) {
            return null;
        }
        String className = head.substring(0, methodDot);
        int classDot = className.lastIndexOf('.');
        if (classDot < 0) {
            return null;
        }
        return className.substring(classDot + 1);
    }
}
